From 244f4623e8950b22514462b192eecfaadb0fbd42 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 18:13:19 +0100
Subject: [PATCH] libtaskmanager: use the desktop file a window was launched
 from

When two desktop files start the same program, its windows share an app
id, so they were always mapped to the program's own desktop file and
icon. Now prefer the desktop file in the process's systemd launch unit.

BUG: 475736
---
 libtaskmanager/tasktools.cpp | 53 ++++++++++++++++++++++++++++++++++++
 libtaskmanager/tasktools.h   |  5 ++++
 2 files changed, 58 insertions(+)

diff --git a/libtaskmanager/tasktools.cpp b/libtaskmanager/tasktools.cpp
index 98542d332f..18ea24543c 100644
--- a/libtaskmanager/tasktools.cpp
+++ b/libtaskmanager/tasktools.cpp
@@ -20,6 +20,7 @@
 #include <PlasmaActivities/ResourceInstance>

 #include <KIO/ApplicationLauncherJob>
+#include <KIO/DesktopExecParser>
 #include <KIO/OpenUrlJob>

 #include <QDir>
@@ -221,12 +222,64 @@ KService::Ptr serviceFromMetadata(const QString &appId, quint32 pid, const QStri
     }

     if (!services.isEmpty()) {
+        // Several desktop files can start the same program (e.g. with other arguments and another icon), and then
+        // all its windows share one appId. Prefer the desktop file the process was actually launched from.
+        const KService::Ptr launchService = serviceFromLaunchScope(pid);
+        if (launchService && launchService->storageId() != services.first()->storageId()) {
+            const QString startupWMClass = launchService->property<QString>(QStringLiteral("StartupWMClass"));
+            const bool wmClassMatches = startupWMClass.isEmpty() || startupWMClass.compare(appId, Qt::CaseInsensitive) == 0
+                || startupWMClass.compare(xWindowsWMClassName, Qt::CaseInsensitive) == 0;
+            const QString executable = KIO::DesktopExecParser::executableName(services.first()->exec());
+            if (wmClassMatches && !executable.isEmpty() && KIO::DesktopExecParser::executableName(launchService->exec()) == executable) {
+                return launchService;
+            }
+        }
+
         return services.first();
     }

     return KService::Ptr(new KService(QString(), QString(), QString()));
 }

+KService::Ptr serviceFromLaunchScope(quint32 pid)
+{
+    if (pid == 0) {
+        return {};
+    }
+
+    QFile cgroupFile(QStringLiteral("/proc/%1/cgroup").arg(QString::number(pid)));
+    if (!cgroupFile.open(QIODevice::ReadOnly | QIODevice::Text)) {
+        return {};
+    }
+
+    // KIO starts applications in units named app-<escaped desktop file name>-<uuid>.scope or app-<...>@<uuid>.service.
+    static const QRegularExpression unitExpression(QStringLiteral("/app-(.+)[-@][0-9a-f]{32}\\.(?:scope|service)$"));
+    QRegularExpressionMatch match;
+    const QList<QByteArray> lines = cgroupFile.readAll().split('\n');
+    for (const QByteArray &line : lines) {
+        if (line.startsWith("0::")) {
+            match = unitExpression.match(QString::fromUtf8(line));
+            break;
+        }
+    }
+    if (!match.hasMatch()) {
+        return {};
+    }
+
+    QByteArray desktopName;
+    const QByteArray escaped = match.captured(1).toUtf8();
+    for (qsizetype i = 0; i < escaped.size(); ++i) {
+        if (escaped.at(i) == '\\' && i + 3 < escaped.size() && escaped.at(i + 1) == 'x') {
+            desktopName += char(escaped.mid(i + 2, 2).toInt(nullptr, 16));
+            i += 3;
+        } else {
+            desktopName += escaped.at(i);
+        }
+    }
+
+    return KService::serviceByDesktopName(QString::fromUtf8(desktopName));
+}
+
